create extension if not exists "pgcrypto";
create type property_status as enum ('draft','published','archived');
create type booking_status as enum ('new','contacted','confirmed','cancelled','completed');
create type contact_preference as enum ('phone','email','whatsapp');
create table public.agents (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, position text not null, bio text not null default '', phone text not null, whatsapp text not null, email text not null, image_path text, image_url text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.properties (id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null, description text not null, property_type text not null, development_name text, development_slug text, status property_status not null default 'draft', price_per_night integer not null check(price_per_night > 0), minimum_nights integer not null default 1 check(minimum_nights > 0), bedrooms integer not null check(bedrooms >= 0), bathrooms numeric(3,1) not null check(bathrooms >= 0), max_guests integer not null check(max_guests > 0), province text not null, city text not null, suburb text not null, address text not null, latitude numeric, longitude numeric, featured boolean not null default false, available boolean not null default true, amenities text[] not null default '{}', agent_id uuid not null references public.agents(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.property_images (id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, storage_path text not null, public_url text not null, alt_text text not null default '', display_order integer not null default 0, is_primary boolean not null default false, created_at timestamptz not null default now());
create table public.bookings (id uuid primary key default gen_random_uuid(), reference_code text not null unique, property_id uuid not null references public.properties(id), agent_id uuid not null references public.agents(id), first_name text not null, last_name text not null, email text not null, phone text not null, whatsapp text not null, check_in date not null, check_out date not null check(check_out > check_in and check_out <= check_in + 5), guests integer not null check(guests > 0), message text, contact_preference contact_preference not null, status booking_status not null default 'new', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index properties_public_filter_idx on public.properties(status, province, city, price_per_night);
create index bookings_admin_idx on public.bookings(status, created_at desc);
alter table public.agents enable row level security; alter table public.properties enable row level security; alter table public.property_images enable row level security; alter table public.bookings enable row level security;
create policy "public reads active agents" on public.agents for select using (active = true);
create policy "public reads published properties" on public.properties for select using (status = 'published');
create policy "public reads property images" on public.property_images for select using (exists(select 1 from public.properties p where p.id=property_id and p.status='published'));
create policy "admins manage agents" on public.agents for all to authenticated using ((auth.jwt()->>'role')='admin') with check ((auth.jwt()->>'role')='admin');
create policy "admins manage properties" on public.properties for all to authenticated using ((auth.jwt()->>'role')='admin') with check ((auth.jwt()->>'role')='admin');
create policy "admins manage images" on public.property_images for all to authenticated using ((auth.jwt()->>'role')='admin') with check ((auth.jwt()->>'role')='admin');
create policy "admins manage bookings" on public.bookings for all to authenticated using ((auth.jwt()->>'role')='admin') with check ((auth.jwt()->>'role')='admin');
insert into storage.buckets (id,name,public) values ('property-images','property-images',true),('agent-images','agent-images',true),('site-assets','site-assets',true) on conflict do nothing;
create policy "public reads property storage" on storage.objects for select using (bucket_id in ('property-images','agent-images','site-assets'));
create policy "admins manage storage" on storage.objects for all to authenticated using ((auth.jwt()->>'role')='admin') with check ((auth.jwt()->>'role')='admin');